'use strict';

const path = require('path');
const { defineCommand } = require('citty');

function renderTask(task) {
  const lines = [];
  const preferred = [
    'id',
    'phase',
    'status',
    'type',
    'skill',
    'agent_id',
    'agent_role',
    'runtime',
    'model_profile',
    'resolved_model',
    'created_at',
    'updated_at',
  ];

  for (const key of preferred) {
    const value = task[key];
    if (value === undefined || value === null || value === '') continue;
    lines.push(`${key}: ${String(value)}`);
  }

  if (task.goal !== undefined) {
    lines.push('goal:');
    lines.push(String(task.goal || ''));
  }

  const remainingKeys = Object.keys(task).filter((key) => !preferred.includes(key) && key !== 'goal');
  for (const key of remainingKeys) {
    const value = task[key];
    if (value === undefined || value === null || value === '') continue;
    if (Array.isArray(value)) {
      lines.push(`${key}:`);
      if (value.length === 0) lines.push('[]');
      else value.forEach((item) => lines.push(`- ${String(item)}`));
      continue;
    }
    if (typeof value === 'object') {
      lines.push(`${key}:`);
      lines.push(JSON.stringify(value, null, 2));
      continue;
    }
    lines.push(`${key}: ${String(value)}`);
  }

  return lines.join('\n');
}

