+import { describe, expect, it, vi } from 'vitest';
+import { VirtualFileFolder } from './VirtualFileFolder';
+import type { VirtualFileAdapter, VirtualFileEntry } from './types';
+
+function entry(name: string, path: string, kind: VirtualFileEntry['kind']): VirtualFileEntry {
+  return { name, path, kind };
+}
+
+function memoryAdapter(tree: Record<string, VirtualFileEntry[]>, files: Record<string, string> = {}): VirtualFileAdapter {
+  return {
+    list: vi.fn((path: string) => tree[path] ?? null),
+    read: vi.fn((path: string) => files[path] ?? null),
+    readBytes: vi.fn((path: string) => {
+      const value = files[path];
+      return value == null ? null : new TextEncoder().encode(value);
+    }),
+  };
+}

